return ['domain'=>'bulk-editor','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'WOLF - WordPress Posts Bulk Editor and Manager Professional 2.1.3','pot-creation-date'=>'2026-11-20T14:15:27+00:00','po-revision-date'=>'2026-11-20 15:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['WOLF - WordPress Posts Bulk Editor and Manager Professional'=>'WOLF - WordPress Posts Bulk Editor and Manager Professional','https://bulk-editor.pro/'=>'https://bulk-editor.pro/','Tools for managing and bulk edit posts, pages and all custom types data in the reliable and flexible way! Be professionals with managing data of your site!'=>'Narzędzia do zarządzania i masowej edycji wpisów, stron i wszystkich niestandardowych typów treści - niezawodnie i elastycznie! Zarządzaj danymi swojej witryny jak profesjonalista!','realmag777'=>'realmag777','https://pluginus.net/'=>'https://pluginus.net/','no rounding'=>'bez zaokrąglania','forbidden'=>'zabronione','Default'=>'Domyślnie','Checkboxes for the posts selection. Use SHIFT button on your keyboard to select multiple rows.'=>'Pola wyboru do zaznaczania wpisów. Przytrzymaj klawisz SHIFT, aby zaznaczyć wiele wierszy.','Thumbnail'=>'Miniatura','Title'=>'Tytuł','Content'=>'Treść','Excerpt'=>'Zajawka','Slug'=>'Uproszczona nazwa (slug)','Status'=>'Status','Comment status'=>'Status komentowania','Can users comment post or not.'=>'Czy użytkownicy mogą komentować wpis.','Open'=>'Otwarte','Closed'=>'Zamknięte','Ping status'=>'Status pingów','A ping is a [this site has new content] notification that invites search engine bots to visit your blog.'=>'Ping to powiadomienie [ta witryna ma nową treść], które zaprasza roboty wyszukiwarek do odwiedzenia Twojego bloga.','Send trackbacks to'=>'Wyślij trackbacki do','Separate multiple URLs with spaces. Ping status should be open! Remove 2 links separated by space, save. After opening you will not see links as they had been pinged! No sense for roll back, its sending is instant. Trackbacks are a way to notify legacy blog systems that you’ve linked to them. If you link other WordPress sites, they’ll be notified automatically using pingbacks, no other action necessary. Do not use these fields for something else. They are parsed many times in core code (69 matches for to_ping); their format is fixed.'=>'Oddziel wiele adresów URL spacjami. Status pingów musi być otwarty! Usuń 2 linki oddzielone spacją i zapisz. Po ponownym otwarciu nie zobaczysz linków, bo zostały już wysłane! Cofanie nie ma sensu, wysyłka jest natychmiastowa. Trackbacki to sposób powiadamiania starszych systemów blogowych, że je linkujesz. Jeśli linkujesz inne witryny WordPress, zostaną powiadomione automatycznie przez pingbacki, bez żadnych dodatkowych działań. Nie używaj tych pól do niczego innego. Są wielokrotnie parsowane w kodzie rdzenia (69 trafień dla to_ping); ich format jest stały.','Post password'=>'Hasło wpisu','Password for private posts'=>'Hasło dla wpisów prywatnych','Menu order'=>'Kolejność menu','Custom ordering position.'=>'Własna pozycja w kolejności.','Author'=>'Autor','Date Published'=>'Data publikacji','Date Published GMT'=>'Data publikacji GMT','Date modified'=>'Data modyfikacji','Date modified GMT'=>'Data modyfikacji GMT','Post parent'=>'Rodzic wpisu','Post type'=>'Typ wpisu','Post mime type'=>'Typ MIME wpisu','Not in bulk edit as there is no built-uploader here, so no sense change mime type. Filtering only! The function is designed specifically for attached records.'=>'Brak w edycji masowej, ponieważ nie ma tu wbudowanego uploadera, więc zmiana typu MIME nie ma sensu. Tylko filtrowanie! Funkcja przeznaczona specjalnie dla załączonych rekordów.','Sticky'=>'Przyklejony','Stick this post to the front page'=>'Przyklej ten wpis na stronie głównej','Yes'=>'Tak','No'=>'Nie','Default posts count per page'=>'Domyślna liczba wpisów na stronę','How many rows shows per page in tab Posts Editor. Max possible value is 100!'=>'Ile wierszy wyświetlać na stronie w zakładce Edytor wpisów. Maksymalnie 100!','Default sort by'=>'Domyślne sortowanie według','Select column by which posts sorting is going after plugin page loaded'=>'Wybierz kolumnę, według której wpisy są sortowane po załadowaniu strony wtyczki','Default sort'=>'Domyślne sortowanie','Select sort direction for Default sort'=>'Wybierz kierunek sortowania dla opcji Domyślne sortowanie','Show button in admin bar'=>'Pokaż przycisk na pasku admina','Show Bulk Editor button in admin bar for quick access to the Posts Editor'=>'Pokaż przycisk edytora masowego na pasku admina dla szybkiego dostępu do Edytora wpisów','Show thumbnail preview'=>'Pokaż podgląd miniatury','Show bigger thumbnail preview on mouse over'=>'Pokaż większy podgląd miniatury po najechaniu myszą','Load beauty switchers'=>'Wczytaj ładne przełączniki','Load beauty switchers instead of checkboxes in the Posts Editor.'=>'Wczytaj ładne przełączniki zamiast pól wyboru w Edytorze wpisów.','Use gutenberg'=>'Użyj Gutenberga','Allows to edit content with the gutenberg editor if its enabled for the selected post type'=>'Pozwala edytować treść w edytorze Gutenberg, jeśli jest włączony dla wybranego typu wpisu','Add fields to the quick search'=>'Dodaj pola do szybkiego wyszukiwania','Adds more fields to quick search fields drop-down on the tools panel. Works only for text fields. Syntax: post_name:Post slug,post_content:Content'=>'Dodaje więcej pól do listy szybkiego wyszukiwania na panelu narzędzi. Działa tylko dla pól tekstowych. Składnia: post_name:Post slug,post_content:Content','Override meta checkbox'=>'Nadpisz meta pole wyboru','By default, the checkbox works with 1 and 0. If you need to redefine these values for example to "yes" or "true". Syntax: meta_key1:yes,meta_key2:true'=>'Domyślnie pole wyboru działa z wartościami 1 i 0. Jeśli chcesz je zmienić, np. na "yes" lub "true". Składnia: meta_key1:yes,meta_key2:true','Bulk Edit'=>'Edycja masowa','Will be edited next:'=>'Zostanie edytowane:','Sure? Delete [%s]?'=>'Na pewno usunąć [%s]?','Bulk deleting'=>'Usuwanie masowe','[%s](s) deleted!'=>'Usunięto [%s]!','Bulk editing'=>'Edycja masowa','[%s](s) edited! Table redrawing ...'=>'Zmieniono [%s]! Odświeżanie tabeli ...','[%s](s) edited!'=>'Zmieniono [%s]!','ATTENTION: Bulk operation is going!'=>'UWAGA: trwa operacja masowa!','binded editing'=>'edycja powiązana','In FREE version of the plugin you can change only next fields: %s'=>'W wersji FREE wtyczki możesz zmieniać tylko pola: %s','In this mode to the all selected [%1$s](s) will be set the value of a [%2$s] field which been edited'=>'W tym trybie wszystkim zaznaczonym [%1$s] zostanie ustawiona wartość edytowanego pola [%2$s]','Select post type you want to manage'=>'Wybierz typ wpisu do zarządzania','title'=>'tytuł','content'=>'treść','excerpt'=>'zajawka','slug'=>'uproszczona nazwa (slug)','password'=>'hasło','send trackbacks to'=>'wyślij trackbacki do','post status'=>'status wpisu','post type'=>'typ wpisu','comment status'=>'status komentowania','ping status'=>'status pingów','sticky posts'=>'przyklejone wpisy','increase by value'=>'zwiększ o wartość','decrease by value'=>'zmniejsz o wartość','increase by %'=>'zwiększ o %','decrease by %'=>'zmniejsz o %','set new'=>'ustaw nowe','delete'=>'usuń','post parent'=>'rodzic wpisu','menu order'=>'kolejność menu','Bulk editing will be applied to: %s'=>'Edycja masowa zostanie zastosowana do: %s','all the [%s] on the site'=>'wszystkich [%s] w witrynie','text'=>'tekst','numeric'=>'liczba','statuses and types'=>'statusy i typy','Do Bulk Edit'=>'Wykonaj edycję masową','terminate bulk operation'=>'przerwij operację masową','Delete [%s]!'=>'Usuń [%s]!','Notes'=>'Uwagi','In red containers wrapped fields which are not possible modify in bulk in FREE version of the plugin!'=>'Pola w czerwonych ramkach nie mogą być edytowane masowo w wersji FREE wtyczki!','In the case of an aborted bulk-operation you can roll back changes in the tab History'=>'W razie przerwania operacji masowej możesz cofnąć zmiany w zakładce Historia','Time by time (one time per week for example) - make the backup of your site database. For example by %s'=>'Od czasu do czasu (np. raz w tygodniu) wykonuj kopię zapasową bazy danych witryny. Na przykład przez %s','this plugin'=>'tę wtyczkę','Documentation'=>'Dokumentacja','select it to use'=>'wybierz, aby użyć','variable'=>'zmienna','TITLE'=>'TYTUŁ','MENU ORDER'=>'KOLEJNOŚĆ MENU','append'=>'dopisz na końcu','prepend'=>'dopisz na początku','new'=>'nowy','replace'=>'zamień','same case'=>'ta sama wielkość liter','ignore case'=>'ignoruj wielkość liter','replace to text'=>'zamień na tekst','Select how to round float values fractions in the numeric fields. Works for numeric meta fields. Read more %s.'=>'Wybierz, jak zaokrąglać ułamki liczb zmiennoprzecinkowych w polach numerycznych. Działa dla numerycznych pól meta. Więcej: %s.','here'=>'tutaj','Selected num fields'=>'Wybrane pola liczbowe','You can select numeric field then make math operation with another numeric field using [+ - * /] value'=>'Możesz wybrać pole liczbowe i wykonać działanie matematyczne z innym polem liczbowym, używając wartości [+ - * /]','Random number'=>'Liczba losowa','Decimal'=>'Dziesiętna','From:'=>'Od:','To:'=>'Do:','You can create random numbers for test filling fields or for SEO tasks'=>'Możesz tworzyć liczby losowe do testowego wypełniania pól lub zadań SEO','taxonomies'=>'taksonomie','remove'=>'usuń','Set: %s'=>'Ustaw: %s','other'=>'inne','select thumbnail'=>'wybierz miniaturę','enter operation value'=>'wpisz wartość operacji','Export'=>'Eksport','Should the export be started?'=>'Czy uruchomić eksport?','Exporting'=>'Eksportowanie','Exported'=>'Wyeksportowano','ATTENTION: Export operation is going!'=>'UWAGA: trwa operacja eksportu!','Export will be applied to: %s'=>'Eksport zostanie zastosowany do: %s','Note: you can change columns set and then set their order in the tab Settings, then save it as columns profile which in future will help you with exporting the [%s] data format quickly without necessary each time set columns order and their set!'=>'Uwaga: możesz zmienić zestaw kolumn i ich kolejność w zakładce Ustawienia, a następnie zapisać go jako profil kolumn, który w przyszłości pozwoli szybko eksportować dane [%s] bez każdorazowego ustawiania kolejności i zestawu kolumn!','Export to CSV'=>'Eksport do CSV','Export to XML'=>'Eksport do XML','Export to Excel'=>'Eksport do Excela','download'=>'pobierz','download XML'=>'pobierz XML','cancel export'=>'anuluj eksport','Current export functionality is just for simple operations and data share, if you need something complex find and use especial plugin for Export WordPress data!'=>'Obecna funkcja eksportu służy tylko do prostych operacji i udostępniania danych. Jeśli potrzebujesz czegoś bardziej złożonego, użyj specjalnej wtyczki do eksportu danych WordPress!','Select CSV data delimiter.'=>'Wybierz separator danych CSV.','Filters'=>'Filtry','Filtering'=>'Filtrowanie','Filtered! Table redrawing ...'=>'Przefiltrowano! Odświeżanie tabeli ...','LIKE'=>'ZAWIERA','EXACT'=>'DOKŁADNIE','NOT'=>'NIE','BEGIN'=>'POCZĄTEK','END'=>'KONIEC','ID'=>'ID','quick search by ...'=>'szybkie wyszukiwanie wg ...','Filter'=>'Filtruj','Reset'=>'Resetuj','Empty'=>'Puste','ID(s). Use comma or/and minus for range'=>'ID. Użyj przecinka i/lub myślnika dla zakresu','[%s] title ...'=>'Tytuł [%s] ...','[%s] content ...'=>'Treść [%s] ...','[%s] excerpt ...'=>'Zajawka [%s] ...','[%s] slug ...'=>'Uproszczona nazwa [%s] ...','[%s] password ...'=>'Hasło [%s] ...','Menu order from'=>'Kolejność menu od','Menu order to'=>'Kolejność menu do','Post parent from'=>'Rodzic wpisu od','Post parent to'=>'Rodzic wpisu do','[%s] status'=>'Status [%s]','Sticky posts'=>'Przyklejone wpisy','By author'=>'Wg autora','Not empty'=>'Niepuste','%s from'=>'%s od','%s to'=>'%s do','test'=>'test','Filters profiles'=>'Profile filtrów','Profiles'=>'Profile','Here you can load previously saved filters profile. After pressing on the load button, Posts Editor data reloading will start immediately!'=>'Tutaj możesz wczytać wcześniej zapisany profil filtrów. Po naciśnięciu przycisku wczytywania natychmiast rozpocznie się przeładowanie danych Edytora wpisów!','Select filter profile to load'=>'Wybierz profil filtrów do wczytania','load'=>'wczytaj','New Filter Profile'=>'Nowy profil filtrów','Here you can type any title and save current filters set. Type here any title and then press Save button OR press Enter button on your keyboard!'=>'Tutaj możesz wpisać dowolny tytuł i zapisać bieżący zestaw filtrów. Wpisz tytuł, a następnie naciśnij przycisk Zapisz LUB klawisz Enter!','You can save filter profile only when you applying filters to the posts.'=>'Profil filtrów można zapisać tylko po zastosowaniu filtrów do wpisów.','Save'=>'Zapisz','Close'=>'Zamknij','History'=>'Historia','Reverting'=>'Przywracanie','Reverted!'=>'Przywrócono!','Wait please while data reverting is going!'=>'Poczekaj, trwa przywracanie danych!','History clearing ...'=>'Czyszczenie historii ...','History is cleared!'=>'Historia wyczyszczona!','ATTENTION: History operation is going!'=>'UWAGA: trwa operacja na historii!','This clears the history of all users for this post type, including the AI agent rows. It cannot be undone. Continue?'=>'Spowoduje to wyczyszczenie historii wszystkich użytkowników dla tego typu wpisu, w tym wierszy agenta AI. Nie można tego cofnąć. Kontynuować?','This clears your own history for this post type. It cannot be undone. Continue?'=>'Spowoduje to wyczyszczenie Twojej historii dla tego typu wpisu. Nie można tego cofnąć. Kontynuować?','WOLF cannot create the database table! Make sure that your mysql user has the CREATE privilege! Do it manually using your host panel phpmyadmin!'=>'WOLF nie może utworzyć tabeli bazy danych! Upewnij się, że użytkownik MySQL ma uprawnienie CREATE! Zrób to ręcznie w panelu hostingu (phpMyAdmin)!','AI agent'=>'Agent AI','user #%d'=>'użytkownik #%d','%s (AI agent)'=>'%s (agent AI)','This history entry is not yours. Only an administrator can roll back or delete the changes of other users.'=>'Ten wpis historii nie należy do Ciebie. Tylko administrator może cofać lub usuwać zmiany innych użytkowników.','Bulk operation'=>'Operacja masowa','state: %s'=>'stan: %s','value been: %s'=>'poprzednia wartość: %s','posts bulked: %s'=>'zmienione wpisy: %s','columns: %s'=>'kolumny: %s','revert'=>'cofnij','History is empty!'=>'Historia jest pusta!','Works for edit-operations and not work with delete-operations!'=>'Działa dla operacji edycji, nie działa dla operacji usuwania!','In FREE version of the plugin it is possible to roll back 2 last operations.'=>'W wersji FREE wtyczki można cofnąć 2 ostatnie operacje.','Per page:'=>'Na stronę:','ALL'=>'WSZYSTKIE','Clear the History'=>'Wyczyść historię','all'=>'wszystkie','solo operations'=>'pojedyncze operacje','bulk operations'=>'operacje masowe','by Author'=>'wg autora','by date from'=>'od daty','clear'=>'wyczyść','by date to'=>'do daty','by fields'=>'wg pól','Prev'=>'Poprz.','of'=>'z','Next'=>'Nast.','Help'=>'Pomoc','The plugin has next info: %1$s, %2$s, %3$s. Also if you have troubles you can %4$s!'=>'Wtyczka oferuje: %1$s, %2$s, %3$s. Jeśli masz problemy, możesz też %4$s!','documentation'=>'dokumentacja','translations'=>'tłumaczenia','FAQ'=>'FAQ','ask for support here'=>'poprosić o wsparcie tutaj','Current version of the plugin is FREE. See the difference between FREE and PREMIUM versions %s'=>'Obecna wersja wtyczki to FREE. Zobacz różnice między wersjami FREE i PREMIUM %s','Some little hints'=>'Kilka małych wskazówek','Can I connect an AI assistant (Claude, ChatGPT, Cursor and others) to WOLF and edit posts by chatting with it? Yes - %s'=>'Czy mogę połączyć asystenta AI (Claude, ChatGPT, Cursor i inne) z WOLF i edytować wpisy, rozmawiając z nim? Tak - %s','here is how to connect it'=>'tutaj opisano, jak go połączyć','If to click on an empty space of the black wp-admin bar, it will get you back to the top of the page'=>'Kliknięcie pustego miejsca na czarnym pasku wp-admin przeniesie Cię na górę strony','How to set the same value for some posts on the same time - %s'=>'Jak ustawić tę samą wartość dla kilku wpisów jednocześnie - %s','How to use - %s'=>'Jak używać - %s','meta field Gallery'=>'pole meta Galeria','Search by posts slugs, which are in non-latin symbols does not work because in the data base they are keeps in the encoded format!'=>'Wyszukiwanie po uproszczonych nazwach wpisów zapisanych znakami nielatyńskimi nie działa, ponieważ w bazie danych są przechowywane w formie zakodowanej!','Click ID of the post in the Posts Editor to see it on the site front.'=>'Kliknij ID wpisu w Edytorze wpisów, aby zobaczyć go na stronie.','Use Enter keyboard button in the Posts Editor for moving to the next posts row cell with saving of changes while edit textinputs. Use arrow Up or arrow Down keyboard buttons in the Posts Editor for moving to the next/previous posts row without saving of changes.'=>'Użyj klawisza Enter w Edytorze wpisów, aby przejść do następnej komórki wiersza z zapisaniem zmian podczas edycji pól tekstowych. Użyj strzałek w górę lub w dół, aby przejść do następnego/poprzedniego wiersza bez zapisywania zmian.','To select range of posts using checkboxes - select first post, press SHIFT key on your PC keyboard and click last post.'=>'Aby zaznaczyć zakres wpisów polami wyboru - zaznacz pierwszy wpis, naciśnij klawisz SHIFT i kliknij ostatni wpis.','If you like WOLF %s about what you liked and what you want to see in future versions of the plugin'=>'Jeśli podoba Ci się WOLF, %s o tym, co Ci się podoba i co chcesz zobaczyć w przyszłych wersjach wtyczki','write us feedback please'=>'napisz do nas opinię','If you have an idea you can %s'=>'Jeśli masz pomysł, możesz %s','share it with us here'=>'podzielić się nim z nami tutaj','Requirements'=>'Wymagania','Recommended min RAM'=>'Zalecana min. ilość RAM','Minimal PHP version is'=>'Minimalna wersja PHP to','Recommended PHP version'=>'Zalecana wersja PHP','Type part of a name, login or e-mail'=>'Wpisz część nazwy, loginu lub e-maila','No matching user who can work with WOLF'=>'Brak pasującego użytkownika, który może pracować z WOLF','Working...'=>'Trwa praca...','Disconnect'=>'Rozłącz','Issue a new key? The old key stops working at once and the assistant using it is disconnected.'=>'Wygenerować nowy klucz? Stary klucz natychmiast przestanie działać, a używający go asystent zostanie rozłączony.','Something went wrong. Reload the page and try again.'=>'Coś poszło nie tak. Odśwież stronę i spróbuj ponownie.','cannot connect: this user can no longer work with WOLF'=>'nie można połączyć: ten użytkownik nie może już pracować z WOLF','no key yet - it is issued when the user opens his settings'=>'brak klucza - jest wydawany, gdy użytkownik otworzy swoje ustawienia','MCP access for users'=>'Dostęp MCP dla użytkowników','Save the settings after changing the list. A user taken off the list loses his key and his connection at once.'=>'Zapisz ustawienia po zmianie listy. Użytkownik usunięty z listy natychmiast traci klucz i połączenie.','Users picked here get a personal MCP key in their own settings and connect an AI assistant under their own WordPress account: the assistant can do exactly what they can do by hand, with their role and field visibility, never more. Two-factor connection is always on for personal keys. Only users who can work with WOLF are offered. The site-wide key above is not affected and stays yours.'=>'Wybrani tutaj użytkownicy otrzymują osobisty klucz MCP w swoich ustawieniach i łączą asystenta AI pod własnym kontem WordPress: asystent może robić dokładnie to, co oni sami ręcznie, w ramach swojej roli i widoczności pól, nigdy więcej. Dla kluczy osobistych dwuskładnikowe połączenie jest zawsze włączone. Do wyboru są tylko użytkownicy, którzy mogą pracować z WOLF. Klucz globalny witryny powyżej nie ulega zmianie i pozostaje Twój.','Your MCP access'=>'Twój dostęp MCP','Address for the assistant:'=>'Adres dla asystenta:','Your personal key:'=>'Twój osobisty klucz:','Regenerate key'=>'Wygeneruj klucz ponownie','Give the assistant the address and this key as a request header: Authorization, with the value "Bearer" followed by a space and the key. Two-factor connection is always on for a personal key: every session starts with a token the assistant shows you, which you confirm below.'=>'Podaj asystentowi adres i ten klucz jako nagłówek żądania: Authorization, o wartości "Bearer", spacji i klucza. Dwuskładnikowe połączenie jest zawsze włączone dla klucza osobistego: każda sesja zaczyna się od tokenu, który pokazuje asystent i który potwierdzasz poniżej.','Confirm assistant connection - paste the token the assistant gave you:'=>'Potwierdź połączenie asystenta - wklej token otrzymany od asystenta:','Confirm connection'=>'Potwierdź połączenie','The administrator gave you MCP access. An assistant connected with your key works as you: it can do what you can do by hand in this plugin, with your role and field visibility. Keep the key private; if it may have leaked, press Regenerate key - the old key and its connection stop working at once.'=>'Administrator przyznał Ci dostęp MCP. Asystent połączony Twoim kluczem działa jako Ty: może robić to, co Ty ręcznie w tej wtyczce, w ramach Twojej roli i widoczności pól. Zachowaj klucz w tajemnicy; jeśli mógł wyciec, naciśnij Wygeneruj klucz ponownie - stary klucz i jego połączenie natychmiast przestaną działać.','You cannot work with WOLF on this site.'=>'Nie możesz pracować z WOLF w tej witrynie.','Only an administrator can do this.'=>'Tylko administrator może to zrobić.','You have no MCP access on this site. Ask the administrator to grant it.'=>'Nie masz dostępu MCP w tej witrynie. Poproś administratora o jego przyznanie.','No user given.'=>'Nie podano użytkownika.','Disconnected.'=>'Rozłączono.','A new key is issued. The old one no longer works - update it in your assistant.'=>'Wydano nowy klucz. Stary już nie działa - zaktualizuj go w swoim asystencie.','That is not a connection token. Copy the whole token the assistant gave you - four groups of eight characters separated by dashes.'=>'To nie jest token połączenia. Skopiuj cały token otrzymany od asystenta - cztery grupy po osiem znaków oddzielone myślnikami.','Connected. Go back to the assistant and tell it you have confirmed.'=>'Połączono. Wróć do asystenta i powiedz, że połączenie zostało potwierdzone.','Not connected'=>'Niepołączony','Connected, last activity %d min ago'=>'Połączono, ostatnia aktywność %d min temu','Only an administrator can confirm a connection.'=>'Tylko administrator może potwierdzić połączenie.','Only an administrator can end a connection.'=>'Tylko administrator może zakończyć połączenie.','No assistant is connected.'=>'Żaden asystent nie jest połączony.','An assistant is connected since %1$s. If it stays idle, the connection ends at %2$s.'=>'Asystent jest połączony od %1$s. Jeśli pozostanie bezczynny, połączenie zakończy się o %2$s.','Recommended: turn on two-factor connection. Without it, anyone who gets hold of the MCP key - from a screenshot, a shared config or a stolen laptop - can work with your site. With it, every assistant session also needs a token that you confirm here yourself, and that expires after %s without use.'=>'Zalecane: włącz dwuskładnikowe połączenie. Bez niego każdy, kto zdobędzie klucz MCP - ze zrzutu ekranu, udostępnionej konfiguracji lub skradzionego laptopa - może pracować z Twoją witryną. Z nim każda sesja asystenta wymaga też tokenu, który sam tu potwierdzasz i który wygasa po %s bez użycia.','Enable the MCP server'=>'Włącz serwer MCP','The MCP server is on: assistants can connect at the address below.'=>'Serwer MCP jest włączony: asystenci mogą łączyć się pod poniższym adresem.','The MCP server is off and no assistant can connect. Choose Yes here: the key and the other MCP settings appear below, and Save switches the server on.'=>'Serwer MCP jest wyłączony i żaden asystent nie może się połączyć. Wybierz tu Tak: poniżej pojawią się klucz i inne ustawienia MCP, a Zapisz włączy serwer.','Off by default. The MCP server lets an AI assistant read and edit the posts of this site over a REST endpoint. While it is off, the endpoint is not registered at all and nothing can reach it. Turn it on only when you are about to connect an assistant, and turn it back off if you stop using one.'=>'Domyślnie wyłączone. Serwer MCP pozwala asystentowi AI czytać i edytować wpisy tej witryny przez punkt końcowy REST. Gdy jest wyłączony, punkt końcowy w ogóle nie jest rejestrowany i nic nie może się z nim połączyć. Włącz go tylko wtedy, gdy zamierzasz połączyć asystenta, a wyłącz, gdy przestaniesz go używać.','MCP secret key'=>'Tajny klucz MCP','Not active: the MCP server is switched off above.'=>'Nieaktywne: serwer MCP jest wyłączony powyżej.','Adding it in claude.ai: its server check will say "Couldn\'t check the server" with 403. That is expected for a server that signs in with a key - press "Continue anyway" and add the header Authorization with the value "Bearer" followed by a space and the key.'=>'Dodawanie w claude.ai: sprawdzenie serwera zgłosi "Couldn\'t check the server" z kodem 403. To oczekiwane dla serwera logującego się kluczem - naciśnij "Continue anyway" i dodaj nagłówek Authorization o wartości "Bearer", spacji i klucza.','How to connect an AI assistant'=>'Jak połączyć asystenta AI','Lets an AI assistant work with the posts of this site through a chat: find them, change them in bulk, roll changes back. Give the assistant the address below and this key as a request header named Authorization, with the value "Bearer" followed by a space and the key. Some clients call it an API key header instead - X-WPBE-KEY works the same way. The key is never accepted in the address itself, because anything written into a URL ends up in server logs, browser history and every proxy along the way. Clear this field and press Save to issue a new key: the old one stops working at once and every connected assistant has to be reconnected.'=>'Pozwala asystentowi AI pracować z wpisami tej witryny przez czat: wyszukiwać je, zmieniać masowo, cofać zmiany. Podaj asystentowi poniższy adres i ten klucz jako nagłówek żądania o nazwie Authorization, o wartości "Bearer", spacji i klucza. Niektórzy klienci nazywają to nagłówkiem klucza API - X-WPBE-KEY działa tak samo. Klucz nigdy nie jest akceptowany w samym adresie, ponieważ wszystko, co trafi do adresu URL, ląduje w logach serwera, historii przeglądarki i każdym serwerze pośredniczącym. Wyczyść to pole i naciśnij Zapisz, aby wydać nowy klucz: stary natychmiast przestanie działać, a każdy połączony asystent będzie musiał połączyć się ponownie.','MCP two-factor connection'=>'Dwuskładnikowe połączenie MCP','recommended'=>'zalecane','This does not switch the MCP server on - that is "Enable the MCP server" above. Two-factor connection takes effect once the server is on.'=>'To nie włącza serwera MCP - robi to opcja "Włącz serwer MCP" powyżej. Dwuskładnikowe połączenie zadziała po włączeniu serwera.','Off by default, recommended. With it on, the MCP key alone is not enough: every assistant session starts by showing you a token, you paste it below and confirm, and only then can the assistant work. The connection ends by itself after %s without activity, so a leaked key is useless without you. One assistant is connected at a time.'=>'Domyślnie wyłączone, zalecane. Po włączeniu sam klucz MCP nie wystarcza: każda sesja asystenta zaczyna się od pokazania Ci tokenu, wklejasz go poniżej i potwierdzasz, dopiero wtedy asystent może pracować. Połączenie kończy się samo po %s bez aktywności, więc wyciekły klucz jest bezużyteczny bez Ciebie. Naraz może być połączony jeden asystent.','Upload images'=>'Prześlij obrazy','Add images to your site'=>'Dodaj obrazy do witryny','The first one becomes the featured image of %s.'=>'Pierwszy zostanie obrazem wyróżniającym wpisu %s.','They go into the media library, ready to put on a post.'=>'Trafią do biblioteki mediów, gotowe do użycia we wpisie.','Drop images here'=>'Upuść obrazy tutaj','or click to choose them'=>'lub kliknij, aby je wybrać','Meta Fields'=>'Pola meta','Meta key cannot be empty!'=>'Klucz meta nie może być pusty!','Enter a post ID!'=>'Podaj ID wpisu!','No meta keys found!'=>'Nie znaleziono kluczy meta!','New meta key'=>'Nowy klucz meta','EXACT (=)'=>'DOKŁADNIE (=)','NOT EXACT (!=)'=>'NIE DOKŁADNIE (!=)','NOT LIKE'=>'NIE ZAWIERA','NOT Empty'=>'NIEPUSTE','In FREE version of the plugin it is possible manipulate with 2 meta fields.'=>'W wersji FREE wtyczki można obsługiwać 2 pola meta.','Add Custom key by hands'=>'Dodaj własny klucz ręcznie','Add'=>'Dodaj','Get meta keys from any post by its ID'=>'Pobierz klucze meta z dowolnego wpisu według jego ID','enter post ID'=>'wpisz ID wpisu','Get'=>'Pobierz','Meta quick search ...'=>'Szybkie wyszukiwanie meta ...','Save meta fields'=>'Zapisz pola meta','move'=>'przenieś','enter title'=>'wpisz tytuł','textinput'=>'pole tekstowe','textarea'=>'obszar tekstowy','checkbox'=>'pole wyboru','calendar'=>'kalendarz','array'=>'tablica','gallery'=>'galeria','string'=>'ciąg znaków','number'=>'liczba','Hello, looks like you bought and installed premium version of WOLF - WordPress Posts Bulk Editor and Manager Professional, please deactivate free version before, then uninstall it. 2 versions of the same plugin cannot be activated on the same time!'=>'Witaj, wygląda na to, że wersja premium WOLF - WordPress Posts Bulk Editor and Manager Professional została zakupiona i zainstalowana. Najpierw dezaktywuj wersję darmową, a potem ją odinstaluj. Dwie wersje tej samej wtyczki nie mogą być aktywne jednocześnie!','If you not familiar with the plugin, firstly'=>'Jeśli nie znasz wtyczki, najpierw','visit this page'=>'odwiedź tę stronę','please'=>'proszę','WOLF Bulk Editor'=>'WOLF Bulk Editor','Posts Editor'=>'Edytor wpisów','Search'=>'Szukaj','Failed'=>'Niepowodzenie','Error'=>'Błąd','ignore'=>'ignoruj','This is not deletable!'=>'Tego nie można usunąć!','no items'=>'brak elementów','none'=>'brak','no data'=>'brak danych','Loading'=>'Wczytywanie','Loaded'=>'Wczytano','Saved'=>'Zapisano','Saving'=>'Zapisywanie','Apply'=>'Zastosuj','Cancel'=>'Anuluj','Canceled'=>'Anulowano','Sure?'=>'Na pewno?','Creating'=>'Tworzenie','Created!'=>'Utworzono!','Duplicating'=>'Duplikowanie','Duplicated!'=>'Zduplikowano!','Deleting'=>'Usuwanie','Deleted!'=>'Usunięto!','Reseting'=>'Resetowanie','Reseted!'=>'Zresetowano!','Upload image'=>'Prześlij obraz','Upload file'=>'Prześlij plik','Fill up the data please!'=>'Uzupełnij dane!','Enter how many time duplicate selected [%s](s)!'=>'Wpisz, ile razy zduplikować zaznaczone [%s]!','Enter how many new [%s](s) to create!'=>'Wpisz, ile nowych [%s] utworzyć!','Text search by title or SKU'=>'Szukaj tekstu w tytule lub SKU','Show: Filters/Bulk Edit/Export'=>'Pokaż: Filtry/Edycja masowa/Eksport','Hide: Filters/Bulk Edit/Export'=>'Ukryj: Filtry/Edycja masowa/Eksport','Per page'=>'Na stronę','Select background color'=>'Wybierz kolor tła','Select text color'=>'Wybierz kolor tekstu','No data available in the table'=>'Brak danych w tabeli','Showing _START_ to _END_ of _TOTAL_ entries'=>'Wyświetlanie _START_ do _END_ z _TOTAL_ pozycji','Showing 0 to 0 of 0 entries'=>'Wyświetlanie 0 do 0 z 0 pozycji','(filtered from _MAX_ total entries)'=>'(przefiltrowano z _MAX_ pozycji)','Loading...'=>'Wczytywanie...','Processing...'=>'Przetwarzanie...','No matching records found'=>'Nie znaleziono pasujących rekordów','First'=>'Pierwsza','Last'=>'Ostatnia','Previous'=>'Poprzednia','the filtered [%s]. To remove filtering press reset button on the tools panel below'=>'przefiltrowane [%s]. Aby usunąć filtrowanie, naciśnij przycisk resetu na panelu narzędzi poniżej','the selected [%s](s)'=>'zaznaczone [%s]','You can reset selection of the [%s](s) by its reset button on the panel of the editor OR uncheck them manually!'=>'Możesz zresetować zaznaczenie [%s] przyciskiem resetu na panelu edytora LUB odznaczyć je ręcznie!','Maybe term(s) with such name(s) already exists!'=>'Możliwe, że termin(y) o takiej nazwie już istnieją!','In FREE version of the plugin you can create one profile only!'=>'W wersji FREE wtyczki można utworzyć tylko jeden profil!','append sub item'=>'dodaj element podrzędny','This field is deactivated in FREE version for bulk edit!'=>'To pole jest nieaktywne w wersji FREE dla edycji masowej!','Posts checked'=>'Zaznaczone wpisy','View the post on the site front'=>'Zobacz wpis w witrynie','Editing of the post on its page'=>'Edycja wpisu na jego stronie','Posts not found!'=>'Nie znaleziono wpisów!','New %s'=>'Nowy %s','copy'=>'kopia','see the post on the site'=>'zobacz wpis w witrynie','Scheduled'=>'Zaplanowano','Later'=>'Później','Hi! Are you enjoying using WOLF – WordPress Posts Bulk Editor Professional?'=>'Cześć! Czy podoba Ci się WOLF – WordPress Posts Bulk Editor Professional?','Yes, I love it'=>'Tak, uwielbiam go','Not really...'=>'Raczej nie...','That\'s awesome! Could you please do us a BIG favor and give it a 5-star rating on %s to help us spread the word and boost our motivation?'=>'Super! Wystaw nam proszę 5 gwiazdek na %s - pomożesz nam dotrzeć do innych i dodasz nam motywacji.','Okay, you deserve it'=>'Dobrze, zasługujecie na to','Nope, maybe later'=>'Nie, może później','I already did'=>'Już zrobione','We are sorry to hear you aren\'t enjoying WOLF. We would love a chance to improve it. Could you take a minute and let us know what we can do better?'=>'Przykro nam, że WOLF Ci się nie podoba. Chętnie go ulepszymy. Poświęć minutę i napisz, co możemy zrobić lepiej.','Give Feedback'=>'Wyślij opinię','No thanks'=>'Nie, dziękuję','Will never reset published date, and for modified date field  will set current time!'=>'Nigdy nie zresetuje daty publikacji, a dla pola daty modyfikacji ustawi bieżący czas!','Product: %s'=>'Produkt: %s','Images (%s)'=>'Obrazy (%s)','Post: %s'=>'Wpis: %s','Array'=>'Tablica','Content[empty]'=>'Treść[pusta]','Not allowed!'=>'Niedozwolone!','Posts (%s)'=>'Wpisy (%s)','Select all'=>'Zaznacz wszystko','Deselect all'=>'Odznacz wszystko','cancel'=>'anuluj','save'=>'zapisz','Set full width'=>'Ustaw pełną szerokość','Columns profiles'=>'Profile kolumn','New Post'=>'Nowy wpis','Duplicate selected post(s).'=>'Duplikuj zaznaczone wpisy.','Delete selected post(s)'=>'Usuń zaznaczone wpisy','Uncheck all selected posts'=>'Odznacz wszystkie zaznaczone wpisy','Reset filters'=>'Resetuj filtry','select all variations'=>'zaznacz wszystkie warianty','Scroll right'=>'Przewiń w prawo','Scroll left'=>'Przewiń w lewo','Detach image of the post'=>'Odłącz obraz od wpisu','drag and drop'=>'przeciągnij i upuść','Close the panel'=>'Zamknij panel','No any post type permitted to edit for site editors. Ask please site administrators for details!'=>'Żaden typ wpisu nie jest dozwolony do edycji dla redaktorów witryny. Szczegóły uzyskasz od administratorów witryny!','Your settings have been saved.'=>'Twoje ustawienia zostały zapisane.','Compatible with WordPress v.%s'=>'Zgodna z WordPress w wersji %s','MCP server is off. Connect your AI assistant to WOLF: switch it on in the Settings tab - click to read how'=>'Serwer MCP jest wyłączony. Połącz asystenta AI z WOLF: włącz go w zakładce Ustawienia - kliknij, aby przeczytać jak','MCP server is on, two-factor connection is off - switching it on in the Settings tab is recommended. Click to read how to connect your AI assistant'=>'Serwer MCP jest włączony, dwuskładnikowe połączenie jest wyłączone - zalecane jest włączenie go w zakładce Ustawienia. Kliknij, aby przeczytać, jak połączyć asystenta AI','MCP server is on, with two-factor connection. Click to read how to connect your AI assistant'=>'Serwer MCP jest włączony, z dwuskładnikowym połączeniem. Kliknij, aby przeczytać, jak połączyć asystenta AI','Upgrade'=>'Ulepsz','ATTENTION! Your version of the WordPress is obsolete. There is no warranty of normal working with the plugin!!'=>'UWAGA! Twoja wersja WordPressa jest przestarzała. Brak gwarancji prawidłowego działania wtyczki!!','Settings'=>'Ustawienia','Select some columns in tab "Settings"'=>'Wybierz kolumny w zakładce "Ustawienia"','Actions'=>'Akcje','Quick search'=>'Szybkie wyszukiwanie','Quick terms search by its name'=>'Szybkie wyszukiwanie terminów po nazwie','create new term'=>'utwórz nowy termin','selected only'=>'tylko zaznaczone','Select all terms'=>'Zaznacz wszystkie terminy','Add Image'=>'Dodaj obraz','Replace all posts images by the selected ones'=>'Zastąp wszystkie obrazy wpisów wybranymi','Add selected images to the already existed ones'=>'Dodaj wybrane obrazy do już istniejących','Delete selected images from the posts'=>'Usuń wybrane obrazy z wpisów','Delete selected images from the posts, also delete them from the media library forever'=>'Usuń wybrane obrazy z wpisów, a także na zawsze z biblioteki mediów','REMEMBER: sequence of data maybe have sense (and maybe not), so be attentive! Do not mix in the same popup window data of array and object data!'=>'PAMIĘTAJ: kolejność danych może mieć znaczenie (lub nie), więc bądź uważny! Nie mieszaj w jednym oknie danych tablicy i obiektu!','Prepend array key/value'=>'Dodaj na początku klucz/wartość tablicy','Prepend object set'=>'Dodaj na początku zestaw obiektu','Append array key/value'=>'Dodaj na końcu klucz/wartość tablicy','Append object set'=>'Dodaj na końcu zestaw obiektu','key'=>'klucz','value'=>'wartość','Note: if horizontal scroll disappeared when it must be visible, click on tab Posts Editor to make it visible'=>'Uwaga: jeśli poziomy pasek przewijania zniknął, gdy powinien być widoczny, kliknij zakładkę Edytor wpisów, aby go pokazać','Columns settings%1$s, columns enabled %2$s'=>'Ustawienia kolumn%1$s, włączone kolumny %2$s','Show all columns'=>'Pokaż wszystkie kolumny','premium version'=>'wersja premium','visible for the site editor'=>'widoczne dla redaktora witryny','cell text or number size'=>'rozmiar tekstu lub liczby w komórce','Save all settings'=>'Zapisz wszystkie ustawienia','General settings'=>'Ustawienia ogólne','Site editors post types'=>'Typy wpisów redaktorów witryny','What post types can edit site editors in the tab Posts Editor. Use comma, example: post,car,page'=>'Jakie typy wpisów redaktorzy witryny mogą edytować w zakładce Edytor wpisów. Oddziel przecinkami, np.: post,car,page','Separate columns and meta for post types'=>'Oddzielne kolumny i meta dla typów wpisów','Each post type has its own set of columns and meta fields.'=>'Każdy typ wpisu ma własny zestaw kolumn i pól meta.','Show content and excerpt text partly'=>'Pokaż treść i zajawkę częściowo','Show part of the text in the content and excerpt edit button'=>'Pokaż fragment tekstu na przycisku edycji treści i zajawki','More settings (implicit)'=>'Więcej ustawień (ukrytych)','Show description'=>'Pokaż opis','Edit'=>'Edytuj','Columns profile'=>'Profil kolumn','Here you can load previously saved columns profile. After pressing on the load button, page reloading will start immediately!'=>'Tutaj możesz wczytać wcześniej zapisany profil kolumn. Po naciśnięciu przycisku wczytywania natychmiast rozpocznie się przeładowanie strony!','Current profile is: %1$s %2$s'=>'Bieżący profil: %1$s %2$s','remove current columns profile'=>'usuń bieżący profil kolumn','Select profile to load'=>'Wybierz profil do wczytania','New Profile'=>'Nowy profil','Here you can type any title and save current columns set and their order. Type here any title and then press Save button OR press Enter button on your keyboard!'=>'Tutaj możesz wpisać dowolny tytuł i zapisać bieżący zestaw kolumn oraz ich kolejność. Wpisz tytuł, a następnie naciśnij przycisk Zapisz LUB klawisz Enter!','Create'=>'Utwórz','New term for [%s]'=>'Nowy termin dla [%s]','New Term(s)'=>'Nowe terminy','Here you can write title for the new term. Use comma to create some new tags on the same time! New terms with already existed names will not be created!'=>'Tutaj wpisz tytuł nowego terminu. Użyj przecinka, aby utworzyć kilka nowych tagów naraz! Nowe terminy o już istniejących nazwach nie zostaną utworzone!','Slug(s) of the new term'=>'Uproszczone nazwy nowych terminów','Here you can write slug for the the new term (optionally). Use comma for slug(s) when you create some on the same time terms, or leave slug field empty to create slug(s) automatically'=>'Tutaj możesz wpisać uproszczoną nazwę nowego terminu (opcjonalnie). Użyj przecinka dla kilku uproszczonych nazw przy tworzeniu kilku terminów naraz lub zostaw pole puste, aby utworzyć je automatycznie','Parent of the new term(s)'=>'Rodzic nowych terminów','Here you can select parent for the the new term (optionally)'=>'Tutaj możesz wybrać rodzica dla nowego terminu (opcjonalnie)','UPGRADE TO FULL VERSION'=>'PRZEJDŹ NA PEŁNĄ WERSJĘ','WOLF - Posts Bulk Editor Professional'=>'WOLF - Posts Bulk Editor Professional','BEAR - Bulk Editor Professional for WooCommerce'=>'BEAR - Bulk Editor Professional for WooCommerce','BEAR - WooCommerce Bulk Editor Professional'=>'BEAR - WooCommerce Bulk Editor Professional']];